import {heroStats,grantXP,addItem} from './campaign-profile.mjs';
import {skillById,stageLoot,experience} from './campaign-growth-data.mjs';
import {groundTarget} from './targeting.mjs?v=20261030-duel12';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function syncSoloStats(w,initial=false){const c=w.campaign;if(!c?.progression)return;const s=heroStats(c.progression,w.hero),p=w.player,dh=s.maxHp-p.maxHp,dm=s.maxMp-(p.maxMp||0);p.maxHp=s.maxHp;p.maxMp=s.maxMp;p.hp=initial?s.maxHp:Math.min(s.maxHp,p.hp+Math.max(0,dh));p.mp=initial?s.maxMp:Math.min(s.maxMp,(p.mp||0)+Math.max(0,dm));c.stats=s;}
export function soloSpec(w,key,base){const c=w.campaign;if(!c?.progression||key==='attack')return base;const s=skillById(c.progression.heroes[w.hero].slots[key]);if(!s)return null;const rank=c.progression.heroes[w.hero].skills[s.id]||0;return {...base,...(s.column?{duration:s.row===2?.9:.55,release:s.row===2?.4:.2}:{}),cd:(s.cd??base.cd)*(1-.02*rank),name:s.name,soloSkill:s};}
export function soloPay(w,key,recast,spec){const c=w.campaign;if(!c?.progression)return true;if(key==='attack')return true;if(!spec?.soloSkill)return false;if(recast)return true;const cost=spec.soloSkill.mana;if(w.player.mp<cost){c.notice='法力不足 · 收集灵露或稍作恢复';c.noticeUntil=w.time+1.4;return false;}w.player.mp-=cost;return true;}
export function soloDamage(w,amount,{castId,soloSkill}={}){const c=w.campaign;if(!c?.progression)return amount;const id=soloSkill||c.castSkills?.[castId]||w.campaignDamageSkill||w.player.cast?.soloSkill?.id,rank=c.progression.heroes[w.hero].skills[id]||0;let result=amount*c.stats.power*(1+rank*.08);const random=c.random||Math.random;if(random()<c.stats.crit)result*=1.5;return Math.max(1,Math.round(result));}
export function soloOnHit(w,t,castId,source,api){const c=w.campaign;if(!c?.progression||source==='soloChain')return;const s=skillById(c.castSkills[castId]);if(!s?.column)return;if(w.hero==='nature'&&s.row===0)t.rootUntil=w.time+.45;if(w.hero==='frost')t.frostSnareUntil=w.time+1.5;if(s.row===1&&['lightning','frost'].includes(w.hero)){c.chained||=new Set();if(c.chained.has(castId))return;c.chained.add(castId);for(const other of w.targets)if(other!==t&&other.hp>0&&Math.hypot(other.x-t.x,other.y-t.y)<150){api.damage(w,other,14,{school:w.hero,castId,source:'soloChain'});if(w.hero==='frost')other.frostSnareUntil=w.time+1.5;}api.effect(w,'soloSkill',{hero:w.hero,row:1,x:t.x,y:t.y-60,size:235,duration:.7});}}
export function soloRelease(w,cast,api){const s=cast.soloSkill;if(!w.campaign?.progression||!s?.column)return false;const p=w.player,row=s.row,hero=w.hero,rank=w.campaign.progression.heroes[hero].skills[s.id]||0,origin=api.castMuzzle(w),dx=cast.x-origin.x,dy=cast.y-origin.y,angle=Math.atan2(dy,dx),floor=groundTarget(w,clamp(cast.x,p.x-580,p.x+580),cast.y)||{x:p.x+p.face*180,y:p.y},fx=(x,y,size=210,duration=.85,ground=false)=>api.effect(w,'soloSkill',{hero,row,x,y,size,duration,ground,soloSkill:s.id,face:p.face});
 const shoot=(a,damage,speed=720,extra={})=>api.projectile(w,'soloBolt',origin.x,origin.y,Math.cos(a),Math.sin(a),speed,damage,{owner:'player',terrainCollision:false,school:hero,fire:hero==='fire',soloHero:hero,soloRow:row,castId:cast.id,life:1.5,...extra});
 if(row===0){if(hero==='fire'){w.campaign.soloFields.push({hero,row,x:floor.x,y:floor.y,r:150,until:w.time+2.2,next:w.time,damage:10,castId:cast.id,root:0});fx(floor.x,floor.y,330,2.2,true);}else if(hero==='lightning'){fx(p.x+p.face*95,p.y-58,250);for(const t of w.targets)if(t.hp>0&&(t.x-p.x)*p.face>=-t.w&&Math.abs(t.x-p.x)<160+t.w&&Math.abs(t.y-p.y)<150)api.damage(w,t,42,{school:hero,knock:p.face*180,castId:cast.id});}else{for(const d of [-.2,0,.2])shoot(angle+d,16,760,{homing:hero==='frost'});fx(origin.x,origin.y,145,.4);}}
 else if(row===1){if(hero==='nature'||hero==='star'){const amount=Math.round(p.maxHp*(hero==='nature'?.13:.08)*(1+rank*.08));p.hp=Math.min(p.maxHp,p.hp+amount);if(hero==='nature')p.enemyStatus={};else p.shield=Math.min(30,(p.shield||0)+12);fx(p.x,p.y,260,1.25,true);}else if(hero==='shadow'){const x=clamp(p.x+Math.cos(angle)*280,35,w.width-35);fx(p.x,p.y-40,190,.75);p.x=p.prevX=x;p.invuln=Math.max(p.invuln,.22);api.area(w,p.x,p.y-50,135,40,{school:hero,castId:cast.id});fx(p.x,p.y-45,260);}else{shoot(angle,hero==='fire'?44:hero==='lightning'?36:32,920,{pierceActors:true,hitIds:[],homing:hero==='frost'});fx(origin.x,origin.y,190,.6);}}
 else{const x=hero==='lightning'?p.x:floor.x,y=hero==='lightning'?p.y:floor.y;w.campaign.soloFields.push({hero,row,x,y,r:hero==='lightning'?165:215,follow:hero==='lightning',until:w.time+3,next:w.time+.25,damage:hero==='nature'?14:20,castId:cast.id,root:hero==='nature'?.35:0});if(hero==='lightning')p.soloGuardUntil=w.time+3;fx(x,y,440,3,true);}
 api.emit(w,'cast',{key:cast.key,heavy:row===2});return true;
}
function drop(w,item,x,y,flags={}){const c=w.campaign,surface=groundTarget(w,x,y-2);c.drops.push({id:'drop-'+(++w.serial),item:{...item},x,y:surface?.y??w.floor,born:w.time,...flags});}
export function soloTick(w,dt,api){const c=w.campaign;if(!c?.progression)return;const p=w.player,profile=c.progression;syncSoloStats(w);p.mp=Math.min(p.maxMp,p.mp+dt*1.2);p.hp=Math.min(p.maxHp,p.hp+dt*c.stats.regen);
 for(const f of c.soloFields){if(f.follow){f.x=p.x;f.y=p.y;}if(w.time>=f.next&&w.time<f.until){f.next=w.time+.5;for(const t of w.targets)if(t.hp>0&&Math.abs(t.x-f.x)<f.r+t.w&&Math.abs(t.y-f.y)<160){api.damage(w,t,f.damage,{school:f.hero,castId:f.castId,root:f.root,impact:false,fire:f.hero==='fire'});if(f.hero==='frost')t.frostSnareUntil=w.time+1.4;}}}c.soloFields=c.soloFields.filter(f=>f.until>w.time);
 for(const t of w.targets){if(t.hp>0||t.rewarded||!t.enemyKind||t.owner||t.egg||t.baby||!t.killedByPlayer)continue;t.rewarded=true;if(t.enemyKind.startsWith('B')){if(!c.bossLooted){c.bossLooted=true;const drops=stageLoot(c.stage.id,c.random);drops.forEach((item,i)=>drop(w,item,t.x+(i-2)*42,w.floor));if(!profile.firstTickets.includes(c.stage.id)||(c.random||Math.random)()<.5)drop(w,{type:'ticket',count:1},t.x+120,w.floor,{firstTicket:!profile.firstTickets.includes(c.stage.id),stage:c.stage.id});if(c.stage.id===1&&!profile.choiceClaimed)drop(w,{type:'heroChoice',count:1},t.x-145,w.floor,{choice:true});}}
  else{const before=experience(profile.heroes[w.hero].exp).level;profile.coins+=5;grantXP(profile,w.hero,5);c.rewardCount++;if(experience(profile.heroes[w.hero].exp).level>before){c.notice='等级提升 · Lv.'+experience(profile.heroes[w.hero].exp).level;c.noticeUntil=w.time+2;syncSoloStats(w);}if(c.recoveryDrops<2&&(c.random||Math.random)()<.035){drop(w,{type:c.recoveryDrops%2?'mana':'health',count:1},t.x,t.y,{recovery:true});c.recoveryDrops++;}}c.dirty=true;}
}
export function pickupSolo(w){const c=w.campaign;if(!c?.progression)return 0;let count=0;for(const d of c.drops){if(d.picked||Math.abs(d.x-w.player.x)>110||Math.abs(d.y-w.player.y)>100)continue;if(d.choice&&c.progression.choiceClaimed){d.picked=true;continue;}if(d.firstTicket&&c.progression.firstTickets.includes(d.stage)){d.picked=true;continue;}addItem(c.progression,d.item);if(d.choice)c.progression.choiceClaimed=true;if(d.firstTicket)c.progression.firstTickets.push(d.stage);d.picked=true;count++;}if(count){c.dirty=true;c.notice=`拾取${count}件物品 · 已放入背包`;c.noticeUntil=w.time+2;}c.drops=c.drops.filter(d=>!d.picked);return count;}
